import{_ as a,o,c as s,a3 as r}from"./chunks/framework.BFeCKmyl.js";const p=JSON.parse('{"title":"SEI mais descritivo e horizontal","description":"","frontmatter":{"title":"SEI mais descritivo e horizontal","id":"sei-mais-descritivo-horizontal","plataforma":"SEI","grupo":"SEI","plano":"free","desde":"1.0.2","padrao":"ligado"},"headers":[],"relativePath":"funcionalidades/sei-mais-descritivo-horizontal.md","filePath":"funcionalidades/sei-mais-descritivo-horizontal.md"}'),t={name:"funcionalidades/sei-mais-descritivo-horizontal.md"};function i(d,e,c,n,l,m){return o(),s("div",null,e[0]||(e[0]=[r('<h1 id="sei-mais-descritivo-e-horizontal" tabindex="-1">SEI mais descritivo e horizontal <a class="header-anchor" href="#sei-mais-descritivo-e-horizontal" aria-label="Permalink to &quot;SEI mais descritivo e horizontal&quot;">​</a></h1><h2 id="o-que-faz" tabindex="-1">O que faz <a class="header-anchor" href="#o-que-faz" aria-label="Permalink to &quot;O que faz&quot;">​</a></h2><p>Na tela de controle de processos do SEI, os marcadores e as descrições aparecem só como ícones ou balões. Este recurso mostra o texto dos marcadores ao lado dos ícones e a especificação de cada processo logo abaixo do número, reorganiza as colunas e destaca as linhas com termos que você escolher, como &quot;urgente&quot;.</p><h2 id="onde-aparece" tabindex="-1">Onde aparece <a class="header-anchor" href="#onde-aparece" aria-label="Permalink to &quot;Onde aparece&quot;">​</a></h2><p><strong>SEI</strong> (<code>*.jus.br/sei/</code>), tela de controle de processos.</p><h2 id="passo-a-passo" tabindex="-1">Passo a passo <a class="header-anchor" href="#passo-a-passo" aria-label="Permalink to &quot;Passo a passo&quot;">​</a></h2><ol><li>Abra a tela de controle de processos do SEI.</li><li>Cada marcador aparece com o texto ao lado do ícone, e a descrição de cada processo aparece em letra menor sob o número.</li><li>As linhas que contêm um dos termos configurados ficam com a cor de destaque.</li></ol><h2 id="configuracoes-e-opcoes" tabindex="-1">Configurações e opções <a class="header-anchor" href="#configuracoes-e-opcoes" aria-label="Permalink to &quot;Configurações e opções&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Opção</th><th>Padrão</th><th>Efeito</th></tr></thead><tbody><tr><td>Termos para destaque (separados por <code>;</code>)</td><td><code>urgente; prioridade;</code></td><td>Linhas que contêm algum desses termos recebem a cor de destaque. Maiúsculas e acentos não importam.</td></tr><tr><td>Cor de destaque</td><td>#a5e491 (verde-claro)</td><td>Cor de fundo das linhas destacadas.</td></tr></tbody></table><h2 id="observacoes" tabindex="-1">Observações <a class="header-anchor" href="#observacoes" aria-label="Permalink to &quot;Observações&quot;">​</a></h2><ul><li>Só atua na tela de controle de processos.</li><li>Trechos repetitivos dos marcadores, como &quot;Informações prestadas no processo&quot;, são omitidos para economizar espaço.</li></ul>',11)]))}const u=a(t,[["render",i]]);export{p as __pageData,u as default};
